from pathlib import Path
import shutil,re
p=next(Path('wiki/books/moduli/m-sp04-prefettizia-diplomatica/chapters').glob('07-*.md'));a=Path('wiki/reviews/correzioni-collana-2026-10-02/archive/pre-correzioni-sp04-07.md');assert not a.exists();shutil.copyfile(p,a);t=p.read_text(encoding='utf8')
t=re.sub(r'> \*\*Accorpamento motivato\.\*\*[^\n]+\n\n','',t)
t=t.replace('Il limite delle quattro prove scritte completate','Il limite delle quattro serie di prove scritte completate e non superate').replace('formazione iniziale almeno biennale','formazione iniziale biennale').replace('il contatore degli scritti completati','il contatore delle serie di scritti completate e non superate').replace('ricostruisce gli scritti completati','ricostruisce le serie di scritti completate e non superate')
t=t.replace('Alla data di riferimento non è disponibile una futura banca ufficiale prefettizia.','Lo stato della banca ufficiale prefettizia richiede il controllo del portale e degli avvisi alla data in cui studi.')
t=t.replace('Prefettizia: codici e fonti non commentati','Prefettizia: scrittura mediante strumenti informatici, codici e fonti non commentati')
t=t.replace('segue le istruzioni per conferma e uscita','segui le istruzioni per conferma e uscita')
t=t.replace("Il titolo di Chiara ha un nome simile a una classe ammessa, ma la classe non compare nella sua scheda.","Chiara prepara il concorso prefettizio 2025. Il suo titolo ha un nome simile a una delle classi ammesse, ma la classe non compare nella scheda personale. Il caso non riguarda il bando diplomatico 2026, che ammette la laurea magistrale o equiparata senza quel medesimo elenco di classi.")
t=t.replace('Le sintesi orientano ma non sostituiscono la fonte.','L’atto ufficiale pertinente stabilisce requisiti e modalità, coordinato con eventuali rettifiche. Una scheda privata può riassumerlo, ma non modificarlo; il ricordo di un candidato non prova il contenuto dell’atto; una tornata precedente va verificata prima del riuso.')
t=t.replace('I dati mobili richiedono un nuovo controllo.','La correttezza storica non dimostra la validità nella nuova procedura. La convenienza personale non incide sulla regola e il controllo non riguarda soltanto i posti: può investire requisiti, programma, strumenti e scadenze.')
t=t.replace('Prima il set non esiste come fonte ufficiale.','Il metodo richiede una raccolta ufficiale effettiva e identificata per versione. Una raccolta online privata non basta; applicarlo sempre inventerebbe un perimetro chiuso; non applicarlo mai rinuncerebbe invece a uno strumento valido quando la condizione è soddisfatta.')
t=t.replace('I dubbi restano da chiarire.','La conclusione deve collegare la regola al fatto personale e alla sua prova: per esempio classe di laurea, certificato e articolo del bando. La sola spunta nasconde il controllo; previsione e opinione non documentano un requisito. Un dubbio aperto conserva il proprio stato.')
t=t.replace('Le interpretazioni vengono separate.','Tempo impiegato, sezioni consegnate ed errori certi sono osservazioni da conservare. La graduatoria dipende dagli esiti ufficiali; diffondere materiale vietato non è uno scopo del debrief; l’impressione immediata non sostituisce la valutazione amministrativa.')
t=t.replace('Le regole generali non determinano la biografia.','Gradi, lingue e accesso per concorso appartengono all’architettura descritta. La prima sede dipende invece da assegnazioni e criteri concreti: la regola generale non consente di promettere una destinazione individuale.')
p.write_text(t,encoding='utf8')
